    };

    const ks = ops?.killSwitches || {};
    const cs = ops?.circuitStates || {};
    const ts = ops?.tokenStats || {};
    const tr = ops?.trustDistribution || {};
    const em = ops?.errorMetrics || {};
    const ue = ops?.unitEconomics || {};
