                    <div className="ops-ue-card" style={{ background: ue.margin < 30 ? 'rgba(239,68,68,0.1)' : 'rgba(34,197,94,0.05)', border: `1px solid ${ue.margin < 30 ? 'rgba(239,68,68,0.2)' : 'rgba(34,197,94,0.1)'}` }}>
