'use client';
import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { createSupabaseClient } from '@/utils/supabase/client';
import { useAuth } from '@/context/AuthContext';
import { copyToClipboard } from '@/lib/utils/clipboard';
import { openWhatsAppShare } from '@/lib/utils/whatsapp';
import { Card, Button, Badge } from '@/components/ui';

export default function BattlegroundPage() {
    const router = useRouter();
    const { user, loading: authLoading } = useAuth();
    const [view, setView] = useState('home'); // home | lobby | test | results
    const [battleId, setBattleId] = useState(null);
    const [inviteCode, setInviteCode] = useState('');
    const [joinCode, setJoinCode] = useState('');
    const [battle, setBattle] = useState(null);
    const [participants, setParticipants] = useState([]);
    const [answers, setAnswers] = useState({});
    const [currentQ, setCurrentQ] = useState(0);
    const [timeLeft, setTimeLeft] = useState(0);
    const [creating, setCreating] = useState(false);
    const [joining, setJoining] = useState(false);
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState('');
    const timerRef = useRef(null);
    const channelRef = useRef(null);
    const startTimeRef = useRef(null);
    const [connected, setConnected] = useState(false);
    const supabase = createSupabaseClient();

    useEffect(() => {
        return () => {
            clearInterval(timerRef.current);
            if (channelRef.current) supabase.removeChannel(channelRef.current);
        };
    }, []);

    // Real-time Supabase Broadcast connection
    useEffect(() => {
        if (!battleId || view === 'test') return;

        // Cleanup existing channel
        if (channelRef.current) {
            supabase.removeChannel(channelRef.current);
        }

        const loadState = async () => {
            try {
                const res = await fetch(`/api/battleground/state?battleId=${battleId}`);
                if (!res.ok) return;
                const data = await res.json();

                if (data.battle) setBattle(data.battle);
                if (data.participants) setParticipants(data.participants);

                // Auto-transition
                if (data.battle?.status === 'active' && !data.mySubmission && view === 'lobby') {
                    setView('test');
                    startTimeRef.current = Date.now();
                    setTimeLeft(data.battle.timeLimitSeconds);
                }
                if (data.battle?.status === 'ended' && view !== 'results') {
                    setView('results');
                }
            } catch (err) {
                console.error('State load error:', err);
            }
        };

        // Load initial state
        loadState();

        // Subscribe to Broadcast
        const channel = supabase.channel(`battle_${battleId}`, {
            config: {
                broadcast: { self: true }
            }
        });

        channel
            .on('broadcast', { event: 'state_update' }, (payload) => {
                // When anyone updates the state, reload the state from API to ensure consistency
                loadState();
            })
            .subscribe((status) => {
                setConnected(status === 'SUBSCRIBED');
            });

        channelRef.current = channel;

        return () => {
            supabase.removeChannel(channel);
            setConnected(false);
        };
    }, [battleId, view]);

    // Timer for the test
    useEffect(() => {
        if (view !== 'test' || timeLeft <= 0) return;
        timerRef.current = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(timerRef.current);
                    handleSubmit();
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timerRef.current);
    }, [view, timeLeft > 0]);

    const handleCreate = async () => {
        setCreating(true); setError('');
        try {
            const res = await fetch('/api/battleground/create', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ questionCount: 20, timeLimitMinutes: 30 })
            });
            const data = await res.json();
            if (!res.ok) { setError(data.error); return; }
            setBattleId(data.battleId);
            setInviteCode(data.inviteCode);
            setView('lobby');
        } catch { setError('Failed to create battleground'); }
        finally { setCreating(false); }
    };

    const handleJoin = async () => {
        if (!joinCode.trim()) { setError('Enter an invite code'); return; }
        setJoining(true); setError('');
        try {
            const res = await fetch('/api/battleground/join', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ inviteCode: joinCode })
            });
            const data = await res.json();
            if (!res.ok) { setError(data.error); return; }
            setBattleId(data.battleId);
            setView('lobby');
            if (channelRef.current) channelRef.current.send({ type: 'broadcast', event: 'state_update', payload: {} });
        } catch { setError('Failed to join'); }
        finally { setJoining(false); }
    };

    const handleStart = async () => {
        try {
            await fetch('/api/battleground/start', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ battleId })
            });
            if (channelRef.current) channelRef.current.send({ type: 'broadcast', event: 'state_update', payload: {} });
        } catch { setError('Failed to start'); }
    };

    const handleSubmit = async () => {
        if (submitting) return;
        setSubmitting(true);
        clearInterval(timerRef.current);
        const timeSpent = Math.round((Date.now() - startTimeRef.current) / 1000);
        const formatted = Object.entries(answers).map(([qId, opt]) => ({ questionId: qId, selectedOption: opt }));
        try {
            await fetch('/api/battleground/submit', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ battleId, answers: formatted, timeSpent })
            });
            // Re-connect to broadcast to notify others of our submission and view results
            supabase.channel(`battle_${battleId}`).send({ type: 'broadcast', event: 'state_update', payload: {} });
            setView('results');
        } catch { setError('Failed to submit'); }
        finally { setSubmitting(false); }
    };

    const formatTime = (s) => `${Math.floor(s / 60).toString().padStart(2, '0')}:${(s % 60).toString().padStart(2, '0')}`;

    if (authLoading) return (
        <div className="bg-loading-wrapper">
            <div className="bg-loading-header">
                <div className="bg-loading-title" />
                <div className="bg-loading-subtitle" />
            </div>
            <div className="bg-loading-grid">
                {[0,1].map(i => <div key={i} className="bg-loading-card" />)}
            </div>
        </div>
    );

    if (!user) return (
        <div className="bg-guest-wrapper">
            <div className="bg-guest-icon">⚔️</div>
            <h2 className="bg-guest-title">Join the Battleground</h2>
            <p className="bg-guest-desc">Sign in to create and join live NEET battles with other aspirants.</p>
            <a href="/login" className="bg-guest-cta">Sign In to Battle</a>
        </div>
    );

    // ===== HOME VIEW =====
    if (view === 'home') return (
        <div>

            <div className="page bg-home-wrapper">
                <div className="page-header bg-home-header">
                    <h1 className="page-title">⚔️ NEET Battleground</h1>
                    <p className="page-subtitle">Challenge up to 200 students. Same questions. Same timer. Highest scorer wins.</p>
                </div>

                {error && <div className="bg-error-banner">{error}</div>}

                <div className="grid grid-2 gap-6">
                    <Card className="bg-home-card">
                        <div className="bg-home-icon">🏟️</div>
                        <h2 className="bg-home-card-title">Create a Battle</h2>
                        <p className="text-muted text-sm bg-home-card-desc">Generate 20 questions and share the invite code with your friends</p>
                        <Button variant="primary" onClick={handleCreate} disabled={creating} className="bg-home-btn">
                            {creating ? '⏳ Creating...' : '🚀 Create Battleground'}
                        </Button>
                    </Card>

                    <Card className="bg-home-card">
                        <div className="bg-home-icon">🎟️</div>
                        <h2 className="bg-home-card-title">Join a Battle</h2>
                        <p className="text-muted text-sm bg-home-card-desc">Enter the 6-character invite code shared by a friend</p>
                        <input
                            value={joinCode} onChange={(e) => setJoinCode(e.target.value.toUpperCase())}
                            placeholder="Enter code (e.g. A3X9K2)"
                            maxLength={6}
                            className="bg-home-input"
                        />
                        <Button variant="success" onClick={handleJoin} disabled={joining} className="bg-home-btn">
                            {joining ? '⏳ Joining...' : '🎮 Join Battle'}
                        </Button>
                    </Card>
                </div>
            </div>
        </div>
    );

    // ===== LOBBY VIEW =====
    if (view === 'lobby') return (
        <div>

            <div className="page bg-lobby-wrapper">
                <div className="bg-lobby-icon">🏟️</div>
                <h1 className="bg-lobby-title">Battleground Lobby</h1>
                <div className="bg-lobby-status-container">
                    <span className={`bg-lobby-status-dot ${connected ? 'bg-lobby-status-dot--connected' : 'bg-lobby-status-dot--disconnected'}`}></span>
                    <span className="bg-lobby-status-text">{connected ? 'LIVE — Real-time WebSockets active' : 'Connecting...'}</span>
                </div>

                {/* Invite Code Display */}
                {inviteCode && (
                    <Card className="bg-invite-card">
                        <div className="text-muted text-sm bg-invite-label">Share This Invite Code</div>
                        <div className="bg-invite-code">
                            {inviteCode}
                        </div>
                        <div className="bg-invite-actions">
                            <Button variant="secondary" onClick={() => copyToClipboard(inviteCode)}>📋 Copy Code</Button>
                            <Button variant="success" onClick={() => {
                                const text = `Join my 200-Player NEET Battleground Mega-Quiz! ⚔️\n\nCode: ${inviteCode}\n\nAccept the challenge here:\nhttps://aineetcoach.com/battleground/invite/${inviteCode}`;
                                openWhatsAppShare(text);
                            }}>📱 WhatsApp</Button>
                        </div>
                    </Card>
                )}

                {/* Participant List */}
                <Card className="bg-participants-card">
                    <h3 className="mb-4">👥 {participants.length} Participants Joined</h3>
                    <div className="flex flex-col gap-2">
                        {participants.map((p, i) => (
                            <div key={i} className="bg-participant-row">
                                <div className={`bg-participant-avatar ${p.isMe ? 'bg-participant-avatar--me' : 'bg-participant-avatar--other'}`}>
                                    {p.name?.[0]?.toUpperCase()}
                                </div>
                                <div>
                                    <div className="font-semibold text-sm">{p.name} {p.isMe && '(You)'}</div>
                                    <div className="text-xs text-muted">Level {p.level}</div>
                                </div>
                            </div>
                        ))}
                    </div>
                </Card>

                {/* Start Button (creator only) */}
                {battle?.creatorId === user?.id && (
                    <Button variant="primary" size="lg" onClick={handleStart} className="bg-start-btn">
                        🚀 Start Battle for Everyone ({participants.length} players)
                    </Button>
                )}
            </div>
        </div>
    );

    // ===== TEST VIEW =====
    if (view === 'test' && battle?.questions) {
        const questions = battle.questions;
        const q = questions[currentQ];

        return (
            <div>
                {/* Test Header */}
                <div className="bg-test-header">
                    <div className="font-bold">⚔️ Battleground</div>
                    <div className={`bg-test-timer ${timeLeft < 60 ? 'bg-test-timer--warning' : 'bg-test-timer--normal'}`}>
                        ⏱️ {formatTime(timeLeft)}
                    </div>
                    <div className="text-sm text-muted">Q {currentQ + 1} / {questions.length}</div>
                </div>

                <div className="page bg-test-wrapper">
                    {/* Progress */}
                    <div className="progress-bar bg-test-progress">
                        <div className="progress-fill" style={{ width: `${((currentQ + 1) / questions.length) * 100}%` }}></div>
                    </div>

                    {/* Question */}
                    <Card className="mb-4">
                        <div className="flex items-center justify-between mb-3">
                            <span className="question-number">Question {currentQ + 1}</span>
                            {q.difficulty && <Badge variant="neutral" className={`difficulty-badge ${q.difficulty}`}>{q.difficulty}</Badge>}
                        </div>
                        <p className="bg-test-q-text">{q.text}</p>
                    </Card>

                    {/* Options */}
                    <div className="flex flex-col gap-3 mb-6">
                        {[
                            { key: 'A', text: q.option_a }, { key: 'B', text: q.option_b },
                            { key: 'C', text: q.option_c }, { key: 'D', text: q.option_d }
                        ].map(opt => (
                            <div key={opt.key}
                                className={`option-card ${answers[q.id] === opt.key ? 'selected' : ''}`}
                                onClick={() => setAnswers(prev => ({ ...prev, [q.id]: opt.key }))}
                                style={{ cursor: 'pointer' }}>
                                <span className="option-label">{opt.key}</span>
                                <span>{opt.text}</span>
                            </div>
                        ))}
                    </div>

                    {/* Navigation */}
                    <div className="bg-test-nav">
                        {currentQ > 0 && <Button variant="secondary" onClick={() => setCurrentQ(currentQ - 1)}>← Previous</Button>}
                        {currentQ < questions.length - 1 ? (
                            <Button variant="primary" onClick={() => setCurrentQ(currentQ + 1)} className="bg-test-next-btn">Next →</Button>
                        ) : (
                            <Button variant="success" onClick={handleSubmit} disabled={submitting} className="bg-test-submit-btn">
                                {submitting ? '⏳ Submitting...' : '✅ Submit & See Results'}
                            </Button>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    // ===== RESULTS VIEW =====
    if (view === 'results') return (
        <div>

            <div className="page bg-results-wrapper">
                <div className="bg-results-icon">🏆</div>
                <h1 className="bg-results-title">Battle Results</h1>
                <p className="text-muted bg-results-meta">
                    {battle?.questionCount} Questions • {participants.length} Participants
                </p>

                {/* Leaderboard */}
                <Card className="bg-leaderboard-card">
                    <h3 className="mb-4">🏅 Final Leaderboard</h3>
                    <div className="flex flex-col gap-3">
                        {participants.map((p, i) => {
                            const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `#${i + 1}`;
                            return (
                                <div key={i} className={`bg-leaderboard-row ${p.isMe ? 'bg-leaderboard-row--me' : 'bg-leaderboard-row--other'}`}>
                                    <div className={`bg-leaderboard-rank ${i < 3 ? 'bg-leaderboard-rank--top' : 'bg-leaderboard-rank--normal'}`}>{medal}</div>
                                    <div style={{ flex: 1 }}>
                                        <div className="font-bold">{p.name} {p.isMe && <span className="bg-leaderboard-me-badge">(You)</span>}</div>
                                        <div className="text-xs text-muted">✅ {p.correct} correct • ❌ {p.incorrect} wrong • ⏱️ {formatTime(p.timeSpent || 0)}</div>
                                    </div>
                                    <div className={`bg-leaderboard-score ${i === 0 ? 'bg-leaderboard-score--first' : 'bg-leaderboard-score--normal'}`}>
                                        {p.score}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </Card>

                <div className="bg-results-actions">
                    <Button variant="primary" onClick={() => { setView('home'); setBattleId(null); setInviteCode(''); setAnswers({}); setCurrentQ(0); }}>🏟️ New Battleground</Button>
                    <Link href="/dashboard"><Button variant="secondary">🏠 Dashboard</Button></Link>
                </div>
            </div>
        </div>
    );

    // Fallback loading
    return (
        <div className="loading-overlay" style={{ minHeight: '100vh' }}>
            <div className="spinner" style={{ width: 40, height: 40 }}></div>
        </div>
    );
}

'use client';
import React, { useState, useEffect } from 'react';

const SUBJECT_CONFIG = {
    physics: { icon: '⚡', color: '#6366f1', label: 'Physics', total: 45 },
    chemistry: { icon: '🧪', color: '#06b6d4', label: 'Chemistry', total: 45 },
    biology: { icon: '🧬', color: '#22c55e', label: 'Biology', total: 90 },
};

function HeatCell({ value, maxValue }) {
    const intensity = value / maxValue;
    const bg = intensity > 0.7 ? 'rgba(239,68,68,0.7)'
        : intensity > 0.4 ? 'rgba(245,158,11,0.5)'
            : intensity > 0 ? 'rgba(34,197,94,0.3)'
                : 'rgba(255,255,255,0.03)';
    return (
        <td style={{ background: bg, textAlign: 'center', padding: '8px 12px', fontWeight: value > 3 ? 800 : 500, color: '#f1f5f9', fontSize: '0.9rem', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
            {value || '—'}
        </td>
    );
}

export default function BlueprintPage() {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [activeSubject, setActiveSubject] = useState('biology'); // Default to biology since it has both
    const [viewType, setViewType] = useState('topic'); // 'topic' or 'chapter'
    const [expandedChapters, setExpandedChapters] = useState({});

    useEffect(() => {
        setLoading(true);
        fetch(`/api/blueprint?viewType=${viewType}`)
            .then(res => res.json())
            .then(d => { setData(d); setLoading(false); })
            .catch(() => setLoading(false));
    }, [viewType]);

    if (loading) {
        return (
            <div>
                <div className="page" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '60vh' }}>
                    <div className="spinner" style={{ width: 40, height: 40 }}></div>
                </div>
            </div>
        );
    }

    const years = data?.years || [2021, 2022, 2023, 2024];
    const subjectData = data?.data?.[activeSubject] || {};
    const cfg = SUBJECT_CONFIG[activeSubject];

    // Sort chapters by total questions (most important first)
    const processedChapters = Object.entries(subjectData)
        .map(([chapter, yearDataOrTopics]) => {
            // Check if this chapter has nested topics (like Zoology) or flat data (like Botany)
            const isNested = typeof Object.values(yearDataOrTopics)[0] === 'object';

            let total = 0;
            let aggYearData = {};
            let subTopics = [];

            if (isNested) {
                // Initialize aggYearData with 0s
                years.forEach(y => aggYearData[y] = 0);

                Object.entries(yearDataOrTopics).forEach(([topicTitle, topicYears]) => {
                    let topicTotal = 0;
                    Object.entries(topicYears).forEach(([y, val]) => {
                        aggYearData[y] += val;
                        topicTotal += val;
                    });
                    total += topicTotal;
                    subTopics.push({
                        topic: topicTitle,
                        yearData: topicYears,
                        total: topicTotal,
                        avg: (topicTotal / years.length).toFixed(1)
                    });
                });

                // Sort subtopics by highest weightage internally
                subTopics.sort((a, b) => b.total - a.total);
            } else {
                aggYearData = yearDataOrTopics;
                total = Object.values(yearDataOrTopics).reduce((a, b) => a + b, 0);
            }

            return {
                chapter,
                yearData: aggYearData,
                total,
                avg: (total / years.length).toFixed(1),
                isNested,
                subTopics,
            };
        })
        .sort((a, b) => b.total - a.total);

    const maxQ = Math.max(...processedChapters.map(c => Math.max(...Object.values(c.yearData))));

    const toggleChapter = (chapter) => {
        setExpandedChapters(prev => ({ ...prev, [chapter]: !prev[chapter] }));
    };

    return (
        <div>

            <div className="page">
                <div className="page-header">
                    <h1 className="page-title">📊 NEET Exam Blueprint</h1>
                    <p className="page-subtitle">Historical question distribution across topics and chapters</p>
                </div>

                {/* View Type Toggle */}
                <div style={{ display: 'flex', gap: 4, background: 'rgba(255,255,255,0.05)', padding: 6, borderRadius: 12, width: 'fit-content', margin: '0 0 24px 0' }}>
                    <button
                        onClick={() => setViewType('topic')}
                        style={{
                            padding: '8px 24px', borderRadius: 8, fontSize: '0.9rem', fontWeight: 600,
                            background: viewType === 'topic' ? '#3b82f6' : 'transparent',
                            color: viewType === 'topic' ? '#fff' : '#94a3b8',
                            border: 'none', cursor: 'pointer', transition: 'all 0.2s'
                        }}
                    >
                        Topic-wise (2021-2024)
                    </button>
                    <button
                        onClick={() => setViewType('chapter')}
                        style={{
                            padding: '8px 24px', borderRadius: 8, fontSize: '0.9rem', fontWeight: 600,
                            background: viewType === 'chapter' ? '#8b5cf6' : 'transparent',
                            color: viewType === 'chapter' ? '#fff' : '#94a3b8',
                            border: 'none', cursor: 'pointer', transition: 'all 0.2s'
                        }}
                    >
                        Chapter-wise (2009-2025)
                    </button>
                </div>

                {/* Subject Tabs */}
                <div style={{ display: 'flex', gap: 12, marginBottom: 24, flexWrap: 'wrap' }}>
                    {Object.entries(SUBJECT_CONFIG).map(([key, cfg]) => (
                        <button
                            key={key}
                            onClick={() => setActiveSubject(key)}
                            style={{
                                padding: '12px 24px',
                                borderRadius: 12,
                                border: activeSubject === key ? `2px solid ${cfg.color}` : '2px solid rgba(255,255,255,0.1)',
                                background: activeSubject === key ? `${cfg.color}22` : 'rgba(255,255,255,0.03)',
                                color: activeSubject === key ? cfg.color : '#94a3b8',
                                fontWeight: 700,
                                fontSize: '1rem',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                            }}
                        >
                            {cfg.icon} {cfg.label} ({cfg.total}Q)
                        </button>
                    ))}
                </div>

                {/* Stats Cards */}
                <div className="grid grid-3 gap-4" style={{ marginBottom: 24 }}>
                    <div className="card" style={{ borderLeft: `4px solid ${cfg.color}` }}>
                        <div className="text-muted text-sm">Total Chapters</div>
                        <div style={{ fontSize: '1.8rem', fontWeight: 900, color: cfg.color }}>{processedChapters.length}</div>
                    </div>
                    <div className="card" style={{ borderLeft: '4px solid #f59e0b' }}>
                        <div className="text-muted text-sm">Questions/Year</div>
                        <div style={{ fontSize: '1.8rem', fontWeight: 900, color: '#f59e0b' }}>{cfg.total}</div>
                    </div>
                    <div className="card" style={{ borderLeft: '4px solid #ef4444' }}>
                        <div className="text-muted text-sm">Highest Weightage</div>
                        <div style={{ fontSize: '1rem', fontWeight: 700, color: '#ef4444' }}>
                            {processedChapters[0]?.chapter || '—'}
                            <span style={{ display: 'block', fontSize: '0.8rem', color: '#94a3b8' }}>
                                ~{processedChapters[0]?.avg} Q/year avg
                            </span>
                        </div>
                    </div>
                </div>

                {/* Heatmap Legend */}
                <div style={{ display: 'flex', gap: 16, marginBottom: 16, alignItems: 'center', fontSize: '0.85rem', color: '#94a3b8' }}>
                    <span>Weightage:</span>
                    <span style={{ padding: '2px 10px', borderRadius: 4, background: 'rgba(34,197,94,0.3)' }}>Low (1-2)</span>
                    <span style={{ padding: '2px 10px', borderRadius: 4, background: 'rgba(245,158,11,0.5)' }}>Medium (3)</span>
                    <span style={{ padding: '2px 10px', borderRadius: 4, background: 'rgba(239,68,68,0.7)' }}>High (4+)</span>
                </div>

                {/* Blueprint Table */}
                <div className="card" style={{ overflowX: 'auto', padding: 0 }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
                        <thead>
                            <tr style={{ background: 'rgba(255,255,255,0.05)' }}>
                                <th style={{ textAlign: 'left', padding: '14px 16px', color: '#f1f5f9', fontWeight: 700, position: 'sticky', left: 0, background: '#0d1322', zIndex: 1 }}>
                                    Chapter / Topic
                                </th>
                                {years.map(y => (
                                    <th key={y} style={{ textAlign: 'center', padding: '14px 12px', color: cfg.color, fontWeight: 700 }}>
                                        {y}
                                    </th>
                                ))}
                                <th style={{ textAlign: 'center', padding: '14px 12px', color: '#f59e0b', fontWeight: 800 }}>Total</th>
                                <th style={{ textAlign: 'center', padding: '14px 12px', color: '#22c55e', fontWeight: 700 }}>Avg</th>
                            </tr>
                        </thead>
                        <tbody>
                            {processedChapters.map((c, i) => (
                                <React.Fragment key={c.chapter}>
                                    <tr
                                        onClick={() => c.isNested && toggleChapter(c.chapter)}
                                        style={{
                                            borderBottom: '1px solid rgba(255,255,255,0.04)',
                                            cursor: c.isNested ? 'pointer' : 'default',
                                            transition: 'background 0.2s',
                                        }}
                                        onMouseEnter={(e) => c.isNested && (e.currentTarget.style.background = 'rgba(255,255,255,0.03)')}
                                        onMouseLeave={(e) => c.isNested && (e.currentTarget.style.background = 'transparent')}
                                    >
                                        <td style={{ padding: '10px 16px', fontWeight: 600, color: '#e2e8f0', position: 'sticky', left: 0, background: i % 2 === 0 ? '#0d1322' : '#111827', zIndex: 1, whiteSpace: 'nowrap' }}>
                                            <span style={{ color: '#64748b', marginRight: 8, fontSize: '0.8rem', fontWeight: 400 }}>#{i + 1}</span>
                                            {c.isNested && (
                                                <span style={{ display: 'inline-block', width: 20, color: '#3b82f6', fontSize: '1.2rem', verticalAlign: 'middle', userSelect: 'none' }}>
                                                    {expandedChapters[c.chapter] ? '▾' : '▸'}
                                                </span>
                                            )}
                                            {c.chapter}
                                        </td>
                                        {years.map(y => (
                                            <HeatCell key={y} value={c.yearData[y] || 0} maxValue={maxQ} />
                                        ))}
                                        <td style={{ textAlign: 'center', padding: '10px 12px', fontWeight: 800, color: '#f59e0b', background: 'rgba(245,158,11,0.08)' }}>{c.total}</td>
                                        <td style={{ textAlign: 'center', padding: '10px 12px', fontWeight: 600, color: '#22c55e' }}>{c.avg}</td>
                                    </tr>

                                    {/* Render Subtopics if expanded */}
                                    {c.isNested && expandedChapters[c.chapter] && c.subTopics.map((topic, tIdx) => (
                                        <tr key={topic.topic} style={{ background: 'rgba(0,0,0,0.2)', borderBottom: '1px solid rgba(255,255,255,0.02)' }}>
                                            <td style={{ padding: '8px 16px 8px 48px', fontWeight: 400, color: '#94a3b8', position: 'sticky', left: 0, background: '#0a0f18', zIndex: 1, whiteSpace: 'nowrap' }}>
                                                <span style={{ color: '#475569', marginRight: 6 }}>↳</span> {topic.topic}
                                            </td>
                                            {years.map(y => (
                                                <HeatCell key={`sub-${y}`} value={topic.yearData[y] || 0} maxValue={maxQ} />
                                            ))}
                                            <td style={{ textAlign: 'center', padding: '8px 12px', fontWeight: 600, color: 'rgba(245,158,11,0.7)', fontSize: '0.85rem' }}>{topic.total}</td>
                                            <td style={{ textAlign: 'center', padding: '8px 12px', fontWeight: 500, color: 'rgba(34,197,94,0.7)', fontSize: '0.85rem' }}>{topic.avg}</td>
                                        </tr>
                                    ))}
                                </React.Fragment>
                            ))}
                            {processedChapters.length === 0 && (
                                <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                                    <td colSpan={years.length + 3} style={{ padding: '60px', textAlign: 'center', color: '#94a3b8' }}>
                                        <div style={{ fontSize: '2rem', marginBottom: 16 }}>🚧</div>
                                        <h3 style={{ margin: '0 0 8px', color: '#f1f5f9' }}>Data coming soon!</h3>
                                        <p style={{ margin: 0 }}>Chapter-wise data for {cfg.label} is currently being compiled by our experts.</p>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pro Tip */}
                <div className="card" style={{ marginTop: 24, borderLeft: '4px solid #6366f1', background: 'rgba(99,102,241,0.05)' }}>
                    <p style={{ fontWeight: 700, color: '#6366f1', margin: '0 0 8px' }}>💡 Strategy Tip</p>
                    <p style={{ color: '#94a3b8', margin: 0, lineHeight: 1.6 }}>
                        Focus on the <strong style={{ color: '#ef4444' }}>red-highlighted chapters</strong> first — they consistently have 4+ questions per year.
                        Mastering the top 10 chapters in each subject can secure 60–70% of marks.
                        Use this data with your Study Plan to prioritize revision.
                    </p>
                </div>
            </div>
        </div>
    );
}

import { getSupabase } from '@/lib/supabase';
import Link from 'next/link';
import { notFound } from 'next/navigation';

export async function generateMetadata({ params }) {
    const { id } = params;
    const supabase = getSupabase();

    // Query battles table, inner join users on user_id
    const { data: battle } = await supabase
        .from('battles')
        .select(`
            *,
            users (name)
        `)
        .eq('id', id)
        .single();

    const challenge = battle ? {
        ...battle,
        creator_name: battle.users?.name,
        creator_xp: battle.users?.xp,
        creator_level: battle.users?.level
    } : null;

    if (!challenge) return { title: 'Challenge Not Found' };

    const title = `🔥 ${challenge.creator_name} (Level ${challenge.creator_level}) challenged you to a NEET duel! ⚔️`;
    const description = `${challenge.creator_name} (Level ${challenge.creator_level} • ${challenge.creator_xp} XP) just generated a high-difficulty 10-question AI Mock Test. Do you have what it takes to beat them?`;

    return {
        title,
        description,
        openGraph: {
            title,
            description,
            url: `https://aineetcoach.com/challenge/${id}`,
            images: [
                {
                    url: '/og-image.png',
                    width: 1200,
                    height: 630,
                    alt: 'AI NEET Coach Challenge',
                },
            ],
            type: 'website',
        },
    };
}

