// Streak color logic — kept in JS because it's dynamic
function streakColor(streak) {
    if (!streak) return 'var(--text-muted)';
    if (streak >= 30) return '#ff7b00';
    if (streak >= 7) return 'var(--biology)'; // orange token
    return 'var(--warning)';
}

