                    }
                ],
                "timeRequired": `PT${question.difficulty === 'hard' ? '90' : question.difficulty === 'easy' ? '30' : '60'}S`,
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": `${correctAnswerText}. ${question.explanation || ''}`
